var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("City");
if (!scene.IsValid()) {
    scene = UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/City.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
}
var roots = scene.GetRootGameObjects();
Sim.PhoneControllerUI phone = null;
SettingsUI settings = null;
foreach (var r in roots) {
    if (phone == null) phone = r.GetComponentInChildren<Sim.PhoneControllerUI>(true);
    if (settings == null) settings = r.GetComponentInChildren<SettingsUI>(true);
}
string FullPath(UnityEngine.Transform tr) {
    string p = tr.name; var t = tr;
    while (t.parent != null) { t = t.parent; p = t.name + "/" + p; }
    return p;
}
if (phone != null) Debug.Log("PhoneControllerUI: " + FullPath(phone.transform) + " iid=" + phone.GetInstanceID());
else Debug.Log("PhoneControllerUI not found");
if (settings != null) Debug.Log("SettingsUI: " + FullPath(settings.transform) + " iid=" + settings.GetInstanceID());
else Debug.Log("SettingsUI not found");
